const http = require("http"), cp = require("child_process"), fs = require("fs");
function symptom(m) { console.error("FAIL: " + m); process.exit(1); }
function broken(m) { console.error("ERROR: " + m); process.exit(2); }
const srv = http.createServer((req, res) => {
  res.setHeader("content-type", "application/json");
  if (req.method === "GET" && /\/pages\/projects\/[^/]+$/.test(req.url)) {
    res.statusCode = 404;
    return res.end(JSON.stringify({ success: false, errors: [{ code: 8000007, message: "Project not found" }], messages: [], result: null }));
  }
  res.statusCode = 500;
  res.end(JSON.stringify({ success: false, errors: [{ code: 1, message: "mock" }], messages: [], result: null }));
});
srv.listen(0, "127.0.0.1", () => {
  const port = srv.address().port;
  const dir = fs.mkdtempSync("/tmp/proj-");
  const env = Object.assign({}, process.env, { CLAUDECODE: "1", CLOUDFLARE_API_TOKEN: "x", CLOUDFLARE_ACCOUNT_ID: "acc", CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port, WRANGLER_SEND_METRICS: "false", WRANGLER_LOG_PATH: "/tmp/wl", XDG_CONFIG_HOME: "/tmp/xdg" });
  const r = cp.spawnSync("/w/node_modules/.bin/wrangler", ["pages", "project", "create", "new-proj", "--production-branch", "main"], { cwd: dir, env, encoding: "utf8", timeout: 60000 });
  srv.close();
  const out = (r.stdout || "") + (r.stderr || "");
  if (r.error) broken("spawn: " + r.error.message);
  if (/Delegating to/.test(out)) { console.log("OK: delegated to Workers"); process.exit(0); }
  symptom("pages project create --production-branch stayed on Pages and was not delegated");
});

